<?php
/** Optional scroll words and adaptive logos: persistence, safety and assets. */
if ( ! defined( 'WP_CLI' ) || ! WP_CLI || home_url() !== getenv( 'MRN_STACK_TEST_HOME' ) || ( '127.0.0.1' !== wp_parse_url( home_url(), PHP_URL_HOST ) && ! str_ends_with( (string) wp_parse_url( home_url(), PHP_URL_HOST ), '.localhost' ) ) || ! current_user_can( 'manage_options' ) ) { throw new RuntimeException( 'An explicitly selected local administrator runtime is required.' ); }
$checks = array(); $expect = static function ( $ok, $label ) use ( &$checks ) { if ( ! $ok ) { throw new RuntimeException( esc_html( $label ) ); } $checks[] = $label; };
$image = absint( explode( ',', getenv( 'MRN_CARD_TEST_IMAGE_IDS' ) ?: '' )[0] ); $expect( 'attachment' === get_post_type( $image ), 'Explicit local image exists' );
$layouts = array_column( acf_get_field( 'field_mrn_page_content_rows' )['layouts'], null, 'name' );
$split_fields = array_column( $layouts['two_column_split']['sub_fields'], null, 'name' ); $nested = array_column( $split_fields['right_column_rows']['layouts'], null, 'name' );
foreach ( array( 'body_text' => array( 'text_presentation', 'word_reveal_target', 'word_reveal_scope', 'word_reveal_from', 'word_reveal_to' ), 'logos' => array( 'logos_grid_min_width', 'logos_grid_column_gap', 'logos_grid_row_gap', 'logos_grid_image_max_width', 'logos_heading_font' ) ) as $layout => $names ) {
	$root_fields = array_column( $layouts[ $layout ]['sub_fields'], null, 'name' ); $nested_fields = array_column( $nested[ $layout ]['sub_fields'], null, 'name' );
	foreach ( $names as $name ) { $expect( isset( $root_fields[ $name ], $nested_fields[ $name ] ) && $root_fields[ $name ]['key'] !== $nested_fields[ $name ]['key'], 'Root/nested fields have isolated keys: ' . $name ); }
}
$copy = '<p>Keep <em>emphasis</em>, <strong>strong text</strong> and <a href="/keep/?one=1&amp;two=2">this link</a>.<br>Keep the break.</p><p>Second paragraph.</p>';
$body = array( 'acf_fc_layout' => 'body_text', 'heading' => 'Keep this heading', 'body_text' => $copy, 'text_presentation' => 'scroll-words', 'word_reveal_target' => 'text', 'word_reveal_scope' => 'split', 'word_reveal_from' => 'medium-gray', 'word_reveal_to' => 'charcoal' );
$grid = array( 'acf_fc_layout' => 'logos', 'logos_presentation' => 'auto-grid', 'display_mode' => 'slider', 'autoplay' => 1, 'heading' => 'Editable client logos', 'heading_tag' => 'p', 'logos_heading_font' => 'body', 'logos_content_width' => '1200px', 'logos_inner_gutter' => '30px', 'logos_section_gap' => '54px', 'logos_grid_min_width' => '72px', 'logos_grid_column_gap' => '60px', 'logos_grid_row_gap' => '30px', 'logos_grid_image_max_width' => '70px', 'logo_items' => array_fill( 0, 18, array( 'image' => $image ) ) );
$id = wp_insert_post( array( 'post_type' => 'page', 'post_status' => 'draft', 'post_title' => 'Owned word and adaptive-logo proof' ), true ); $expect( ! is_wp_error( $id ) && $id > 0, 'Owned draft created' );
try {
	$split = array( 'acf_fc_layout' => 'two_column_split', 'column_rows_mode' => 'stack', 'right_column_rows' => array( $body, $grid ) );
	update_field( 'field_mrn_page_content_rows', wp_slash( array( $body, $grid, $split ) ), $id ); acf_flush_value_cache( $id, 'page_content_rows' ); $saved = get_field( 'page_content_rows', $id );
	foreach ( array( 'text_presentation', 'word_reveal_target', 'word_reveal_scope', 'word_reveal_from', 'word_reveal_to' ) as $name ) { $expect( $body[ $name ] === $saved[0][ $name ] && $body[ $name ] === $saved[2]['right_column_rows'][0][ $name ], 'Root/nested word setting persists: ' . $name ); }
	foreach ( array( 'logos_presentation', 'logos_heading_font', 'logos_grid_min_width', 'logos_grid_column_gap', 'logos_grid_row_gap', 'logos_grid_image_max_width' ) as $name ) { $expect( $grid[ $name ] === $saved[1][ $name ] && $grid[ $name ] === $saved[2]['right_column_rows'][1][ $name ], 'Root/nested adaptive setting persists: ' . $name ); }
	$expect( $copy === get_post_meta( $id, 'page_content_rows_0_body_text', true ) && $copy === get_post_meta( $id, 'page_content_rows_2_right_column_rows_0_body_text', true ), 'Rich text, paragraphs, break, emphasis and query link remain exact' );
	$expect( 18 === count( $saved[1]['logo_items'] ) && 18 === count( $saved[2]['right_column_rows'][1]['logo_items'] ), 'Every repeated logo instance remains editable' );
	ob_start(); mrn_base_stack_render_builder_rows( $saved, $id, 'page_content_rows' ); $html = ob_get_clean();
	$expect( 2 === substr_count( $html, 'data-mrn-scroll-words=' ) && ! str_contains( $html, 'data-mrn-motion-effect=' ), 'Only selected text targets emit the separate native word contract' );
	$expect( 2 === substr_count( $html, 'has-auto-grid-logos' ) && 36 === substr_count( $html, '<img ' ) && ! str_contains( $html, 'splide__' ), 'Adaptive presentation keeps all images and ignores dormant slider/autoplay' );
	$expect( 2 === substr_count( $html, '<em>emphasis</em>' ) && 2 === substr_count( $html, 'href="/keep/?one=1&amp;two=2"' ), 'Server HTML remains semantic and fully readable before JavaScript' );
	foreach ( array( '--mrn-logos-grid-min-width:72px', '--mrn-logos-grid-column-gap:60px', '--mrn-logos-grid-row-gap:30px', '--mrn-logos-grid-image-max-width:70px', 'has-logos-heading-font-body' ) as $fragment ) { $expect( str_contains( $html, $fragment ), 'Native output contains ' . $fragment ); }
	$needs = mrn_base_stack_get_front_end_component_needs_for_post( $id ); $expect( ! empty( $needs['presentation'] ) && empty( $needs['slider'] ) && empty( $needs['motion'] ), 'Word effect uses existing presentation runtime; grid adds no slider or timed-effect payload' );
	$markup_needs = mrn_base_stack_collect_front_end_component_needs_from_content( '<p data-mrn-scroll-words="{}">Word color</p>', array() ); $expect( ! empty( $markup_needs['presentation'] ) && empty( $markup_needs['motion'] ), 'Rendered word marker discovers presentation assets without timed motion' );
	$expect( array() === mrn_base_stack_get_scroll_word_attributes( $body, 'heading' ), 'Unselected target emits no word attributes' );
	$plain = array_replace( $body, array( 'text_presentation' => '' ) ); $expect( array() === mrn_base_stack_get_scroll_word_attributes( $plain, 'text' ), 'Unset presentation ignores dormant word settings' );
	foreach ( array( array( 'word_reveal_from' => 'unknown' ), array( 'word_reveal_to' => 'red;display:none' ), array( 'word_reveal_scope' => 'body > *' ), array( 'word_reveal_target' => 'everything' ), array( 'word_reveal_from' => array( 'medium-gray' ) ), array( 'motion_settings' => array( 'enabled' => 1 ) ) ) as $bad ) { $expect( array() === mrn_base_stack_get_scroll_word_attributes( array_replace( $body, $bad ), 'text' ), 'Unknown palette, unsafe target/scope and competing motion cannot emit attributes' ); }
	foreach ( array( '-1px', '1px;color:red', 'var(--unknown)', array( '72px' ) ) as $bad ) { $contract = mrn_base_stack_get_labeled_logos_contract( array( 'logos_presentation' => 'auto-grid', 'logos_grid_min_width' => $bad, 'logos_grid_column_gap' => $bad, 'logos_grid_row_gap' => $bad, 'logos_grid_image_max_width' => $bad ) ); $expect( empty( $contract['attributes'] ), 'Unsafe adaptive lengths cannot emit CSS' ); }
	$plain = $grid; $plain['logos_presentation'] = ''; ob_start(); mrn_base_stack_render_builder_row( $plain, $id, 0 ); $html = ob_get_clean(); $expect( str_contains( $html, 'splide__' ) && ! str_contains( $html, 'has-auto-grid-logos' ), 'Unselected adaptive presentation retains original slider behavior' );
} finally { wp_delete_post( $id, true ); }
$expect( null === get_post( $id ), 'Owned proof draft removed' );
WP_CLI::line( wp_json_encode( array( 'result' => 'passed', 'count' => count( $checks ), 'checks' => $checks, 'candidate_only' => true ), JSON_PRETTY_PRINT ) );
